insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ('ats_panel','ats-panel-63a-400a','Automatic Transfer Switch Panel 63–400 A','لوحة تحويل أوتوماتيكي ATS من 63 إلى 400 أمبير',40,275,null,null,'Wall- or floor-mounted ATS panels that switch your load from mains to generator in seconds when power fails — and back again when it returns. Motorised changeover or contactor based, 3- or 4-pole.','لوحات ATS جدارية أو أرضية تنقل الحمل من الكهرباء العامة إلى المولد خلال ثوانٍ عند انقطاع التيار، وتعيده تلقائياً عند عودته. بمفتاح تحويل مُحرّك أو كونتاكتور، 3 أو 4 أقطاب.','[{"label_en":"Current rating","label_ar":"التيار المقنن","value_en":"63 – 400 A","value_ar":"63 – 400 أمبير"},{"label_en":"Poles","label_ar":"الأقطاب","value_en":"3P or 4P (switched neutral)","value_ar":"3 أو 4 أقطاب (فصل التعادل)"},{"label_en":"Controller","label_ar":"وحدة التحكم","value_en":"Auto mains-failure with adjustable timers","value_ar":"كشف انقطاع تلقائي مع مؤقتات قابلة للضبط"},{"label_en":"Enclosure","label_ar":"الغلاف","value_en":"IP54 powder-coated steel (IP65 option)","value_ar":"حديد مطلي IP54 (خيار IP65)"},{"label_en":"Testing","label_ar":"الاختبار","value_en":"Factory function-tested before dispatch","value_ar":"مختبرة وظيفياً قبل الشحن"}]'::jsonb,'/datasheets/4u-datasheet-placeholder.pdf',array['/images/products/ats-panel.svg']::text[],110,true) on conflict (slug) do nothing;
