insert into public.testimonials (client_name,client_company,country,quote_en,quote_ar,rating,is_published) values ('Operations Manager','Logistics company, Sharjah','uae','They sized the generator and ATS together and delivered from SAIF Zone within days. The WhatsApp updates meant we always knew where the order stood.','قاموا باختيار المولد ولوحة ATS معاً وسلّموا من المنطقة الحرة خلال أيام، ومتابعة الواتساب جعلتنا نعرف حالة الطلب دائماً.',5,false);
